    if (k <= 0) return false; // invalid divisor
    if (arr.length % 2 != 0) return false; // must be even length

    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k; // handle negative numbers
        freq[r]++;
    }

    // remainder 0 must pair among themselves
    if (freq[0] % 2 != 0) return false;

    for (int r = 1; r < k; r++) {
        int complement = k - r;
        if (r == complement) { // occurs when k is even and r == k/2
            if (freq[r] % 2 != 0) return false;
        } else {
            if (freq[r] != freq[complement]) return false;
        }
    }

    return true;
}

