public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    // dp[k] holds all possible sums using k elements
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] dp = new HashSet[n / 2 + 1];
    for (int i = 0; i <= n / 2; i++) dp[i] = new HashSet<>();
    dp[0].add(0);
    for (int num : nums) {
        // iterate k from high to low to avoid reuse of same element
        for (int k = Math.min(n / 2, n); k >= 1; k--) {
            for (int prevSum : dp[k - 1]) {
                dp[k].add(prevSum + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        int fromPrev = dp[i - 1] + cost[i - 1];
        int fromPrevPrev = dp[i - 2] + cost[i - 2];
        dp[i] = Math.min(fromPrev, fromPrevPrev);
    }
    return dp[n];
}

public int uniqueMorseRepresentations(String[] words) {
