        return 0;
    }
    int maxSoFar = nums[0];
    int minSoFar = nums[0];
    int currentMax = nums[0];
    int currentMin = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int num = nums[i];
        currentMax = Math.max(num, currentMax + num);
        maxSoFar = Math.max(maxSoFar, currentMax);
        currentMin = Math.min(num, currentMin + num);
        minSoFar = Math.min(minSoFar, currentMin);
    }
    return Math.max(maxSoFar, -minSoFar);
}

public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    int[] fibs = new int[50]; // 50 is enough for int range
    int size = 0;
    fibs[size++] = 1;
    fibs[size++] = 1;
    while (true) {
        int next = fibs[size - 1] + fibs[size - 2];
        if (next > k) {
            break;
        }
        fibs[size++] = next;
    }

    // Greedy subtraction from largest to smallest
    int count = 0;
    int remaining = k;
    for (int i = size - 1; i >= 0 && remaining > 0; i--) {
        if (fibs[i] <= remaining) {
            remaining -= fibs[i];
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    List<Integer> small = new ArrayList<>();
    List<Integer> large = new ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i != n / i) {
                large.add(n / i);
            }
        }
    }
    Collections.reverse(large);
    List<Integer> all = new ArrayList<>(small);
    all.addAll(large);
    return k <= all.size() ? all.get(k - 1) : -1;
}

