public String getSmallestString(int n, int k) {
    // Start with all 'a's, which gives the minimal sum of n.
    char[] result = new char[n];
    java.util.Arrays.fill(result, 'a');
    int remaining = k - n; // amount of value we need to add to reach k

    // Distribute the remaining value from the end to keep the string lexicographically smallest.
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // each character can increase by at most 25 ('a' -> 'z')
        result[i] = (char) ('a' + add);
        remaining -= add;
    }

    return new String(result);
}

