public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] horiz = new int[m][n];
    int[][] vert = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];
    int maxLen = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horiz[i][j] = (j > 0 ? horiz[i][j - 1] : 0) + 1;
                vert[i][j] = (i > 0 ? vert[i - 1][j] : 0) + 1;
                diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                anti[i][j] = (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0) + 1;
                int localMax = Math.max(Math.max(horiz[i][j], vert[i][j]),
                                        Math.max(diag[i][j], anti[i][j]));
                if (localMax > maxLen) {
                    maxLen = localMax;
                }
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    long num = Math.abs((long) n);
    java.util.ArrayList<String> groups = new java.util.ArrayList<>();
    while (num > 0) {
        long part = num % 1000;
        num /= 1000;
        groups.add(String.format("%03d", part));
    }
    StringBuilder sb = new StringBuilder();
    for (int i = groups.size() - 1; i >= 0; i--) {
        if (i == groups.size() - 1) {
            sb.append(Integer.parseInt(groups.get(i)));
        } else {
            sb.append('.').append(groups.get(i));
        }
    }
    if (negative) {
        sb.insert(0, '-');
    }
    return sb.toString();
}

